-- นำเข้าข้อมูลวัตถุดิบ 3 หมวดจาก Excel (ประวัติเต็ม) — รันหลัง RUN_ON_PROD_materials.sql
-- idempotent: ลบ import เดิม แล้วใส่ใหม่ + คำนวณคงเหลือจากยอดล่าสุด
begin;
delete from material_move where note = 'นำเข้าจาก Excel';


-- ตั้งคงเหลือ = balance ของ move ล่าสุดต่อรายการ (เฉพาะที่มี import)
update material_item mi set qty = sub.bal, updated_at = now()
from (select distinct on (item_id) item_id, balance as bal from material_move where note='นำเข้าจาก Excel' order by item_id, created_at desc, id desc) sub
where sub.item_id = mi.id;
commit;
